def is_near(distance_m: float) -> bool:
    # 参数distance_m是本次调用的局部名字。
    if distance_m < 0:
        return False         # 条件命中立刻结束，后面语句不执行。
    return distance_m <= 35.0

def describe(distance_m: float) -> str:
    near = is_near(distance_m)  # 在一个函数里调用另一个函数。
    if near:
        return "距离提示"
    return "正常距离"

message = describe(34.0)        # 调用describe，得到返回的字符串。
print(message)
print(is_near(42.0))

