def parse_speed(raw: str) -> float:
    try:
        speed = float(raw)               # 可能抛ValueError。
    except ValueError as exc:
        raise ValueError(f"车速不是数字：{raw!r}") from exc
    if not 0.0 <= speed <= 250.0:
        raise ValueError("车速超出约定范围")
    return speed

for text in ["72.0", "oops", "300"]:
    try:
        speed = parse_speed(text)
        print("成功", speed)
    except ValueError as exc:
        print("拒绝", exc)

